def conflicts(rules):
    """rules: a list of (rule_id, kind, limit, action), kind "above" or "up to".

    "above L" covers amounts greater than L; "up to L" covers amounts from 0 to L inclusive.
    Return the (id_a, id_b) pairs, in input order, whose ranges overlap with different actions.
    """
    def span(kind, limit):
        return (limit, float("inf")) if kind == "above" else (0, limit)

    found = []
    for i, (id_a, kind_a, limit_a, action_a) in enumerate(rules):
        for id_b, kind_b, limit_b, action_b in rules[i + 1:]:
            if kind_a != kind_b:
                continue
            (lo_a, hi_a), (lo_b, hi_b) = span(kind_a, limit_a), span(kind_b, limit_b)
            if action_a != action_b and max(lo_a, lo_b) < min(hi_a, hi_b):
                found.append((id_a, id_b))
    return found

